"""Unit E: Exceptions, files and modules."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("exception-hierarchy", "medium", "What is printed?", "print(issubclass(KeyError, LookupError), issubclass(ValueError, ArithmeticError), issubclass(KeyboardInterrupt, Exception))", "True False False", ["True False True", "False False False", "True True False"], "KeyError derives from LookupError. KeyboardInterrupt derives from BaseException, not Exception, so `except Exception` does not catch it."),
        M("exception-hierarchy", "easy", "Why is a bare `except:` generally discouraged?", "It also catches SystemExit and KeyboardInterrupt and hides real bugs", ["It is a syntax error", "It only catches TypeError", "It is slower than any other form"], "Catch the specific exceptions you can handle; at most use `except Exception`."),
        O("try-except", "medium", "What is printed?", "def f():\n    try:\n        return 'try'\n    finally:\n        print('finally', end=' ')\n\nprint(f())", "finally try", ["try", "try finally", "finally"], "finally runs before the function actually returns, so its print comes first."),
        O("try-except", "medium", "What is printed?", "for v in ['5', 'x']:\n    try:\n        n = int(v)\n    except ValueError:\n        print('bad', end=' ')\n    else:\n        print('ok', n, end=' ')\n    finally:\n        print('|', end=' ')", "ok 5 | bad |", ["ok 5 bad |", "ok 5 | bad", "bad | ok 5 |"], "else runs only when no exception occurred; finally always runs."),
        O("raising", "medium", "What is printed?", "try:\n    try:\n        1 / 0\n    except ZeroDivisionError as e:\n        raise ValueError('wrapped') from e\nexcept ValueError as v:\n    print(type(v.__cause__).__name__)", "ZeroDivisionError", ["ValueError", "None", "Exception"], "`raise ... from e` records the original as __cause__ for a clear chained traceback."),
        M("raising", "easy", "What does a bare `raise` inside an except block do?", "Re-raises the exception currently being handled, preserving its traceback", ["Raises a new generic Exception", "Silently ends the program", "Clears the exception"], "Use it to log and propagate without losing the original traceback."),
        O("custom-exceptions", "medium", "What is printed?", "class AppError(Exception):\n    pass\nclass NotFound(AppError):\n    pass\n\ntry:\n    raise NotFound('x')\nexcept AppError as e:\n    print(type(e).__name__, e)", "NotFound x", ["AppError x", "NotFound", "Exception x"], "Catching the base class handles subclasses; the instance is still a NotFound."),
        M("custom-exceptions", "medium", "Why define a project-specific base exception class?", "So callers can catch all your library's errors with one except clause without catching unrelated ones", ["Because Python requires custom exceptions to be registered", "To make exceptions faster", "To avoid using try/except"], "A shared base (e.g. AppError) groups related failures into one catchable family."),
        O("context-managers", "medium", "What is printed?", "class R:\n    def __enter__(self):\n        print('open'); return self\n    def __exit__(self, t, v, tb):\n        print('close'); return False\n\ntry:\n    with R():\n        raise KeyError('k')\nexcept KeyError:\n    print('handled')", "open\nclose\nhandled", ["open\nhandled", "open\nclose", "open\nhandled\nclose"], "__exit__ runs even when the body raises; returning False lets the exception propagate."),
        M("context-managers", "easy", "What is the main benefit of `with open(path) as f:`?", "The file is closed automatically, even if an exception occurs", ["The file is loaded entirely into memory", "The file becomes read-only for other programs", "It makes reads faster"], "The context manager guarantees cleanup, preventing resource leaks."),
        O("file-io", "medium", "What is printed?", "p = '/tmp/demo.txt'\nwith open(p, 'w') as f:\n    f.write('a\\nb\\n')\nwith open(p) as f:\n    lines = f.read().splitlines()\nwith open(p, 'a') as f:\n    f.write('c')\nwith open(p) as f:\n    print(lines, len(f.read()))", "['a', 'b'] 5", ["['a', 'b'] 4", "['a\\n', 'b\\n'] 5", "['a', 'b', 'c'] 5"], "'w' truncates, 'a' appends. The final file is 'a\\nb\\nc': five characters."),
        M("file-io", "medium", "What is the memory-friendly way to process a huge text file line by line?", "Iterate over the file object: for line in f", ["f.read() then split", "f.readlines() into a list", "Load it with a list comprehension of f.read()"], "Iterating a file reads lazily, one line at a time, keeping memory constant."),
        O("text-binary", "medium", "What is printed?", "data = 'héllo'.encode('utf-8')\nprint(len('héllo'), len(data), data[:2], data.decode('utf-8') == 'héllo')", "5 6 b'h\\xc3' True", ["5 5 b'h\\xc3' True", "6 5 b'h\\xc3' True", "5 6 b'he' True"], "é is one character but two bytes in UTF-8, so the byte string is longer than the text."),
        M("text-binary", "easy", "Which mode should you use to read an image file?", "'rb' (binary)", ["'r' (text)", "'rt'", "'w'"], "Binary mode returns bytes without newline translation or decoding."),
        O("paths", "medium", "What is printed?", "from pathlib import Path\np = Path('/data/logs/app.tar.gz')\nprint(p.name, p.suffix, p.stem, p.parent.name, p.with_suffix('.txt').name)", "app.tar.gz .gz app.tar logs app.tar.txt", ["app.tar.gz .tar.gz app logs app.txt", "app.tar.gz .gz app logs app.tar.txt", "app .gz app.tar logs app.tar.txt"], "suffix is only the last extension; stem removes just that one."),
        M("paths", "easy", "Why prefer pathlib.Path over string concatenation for file paths?", "It handles separators across operating systems and offers readable methods like / and .exists()", ["Strings cannot represent paths", "pathlib is required by open()", "Path objects are mutable"], "`Path('a') / 'b'` builds correct paths on every platform."),
        O("json-handling", "medium", "What is printed?", "import json\ns = json.dumps({'a': (1, 2), 'b': None, 'c': True})\nprint(s, json.loads(s)['a'])", "{\"a\": [1, 2], \"b\": null, \"c\": true} [1, 2]", ["{'a': (1, 2), 'b': None, 'c': True} (1, 2)", "{\"a\": [1, 2], \"b\": None, \"c\": True} [1, 2]", "{\"a\": [1, 2], \"b\": null, \"c\": true} (1, 2)"], "JSON has arrays, null and true, so tuples become lists and round-trip as lists."),
        M("json-handling", "medium", "What does json.loads raise for malformed text?", "json.JSONDecodeError (a subclass of ValueError)", ["KeyError", "SyntaxError", "It returns None"], "Catch JSONDecodeError (or ValueError) around untrusted input."),
        O("csv-handling", "medium", "What is printed?", "import csv, io\nrows = list(csv.DictReader(io.StringIO('n,s\\nann,5\\nbob,7\\n')))\nprint(rows[1]['n'], sum(int(r['s']) for r in rows))", "bob 12", ["bob 57", "ann 12", "TypeError"], "DictReader yields dicts keyed by the header row; values are strings until converted."),
        M("csv-handling", "medium", "Why open CSV files with newline='' when using the csv module?", "So the csv module controls line endings and handles newlines inside quoted fields correctly", ["To make the file read-only", "To speed up reading", "To decode UTF-8"], "The documentation recommends newline='' to avoid extra blank lines and broken embedded newlines."),
        M("modules-packages", "easy", "What turns a directory into a regular importable package?", "Traditionally an __init__.py file (namespace packages work without one)", ["A setup.cfg file", "A requirements.txt file", "A directory name starting with an underscore"], "__init__.py marks a regular package and can expose its public API."),
        O("modules-packages", "medium", "What is printed?", "import math as m\nfrom math import pi as P\nprint(m.floor(P), m.__name__)", "3 math", ["3 m", "3.14 math", "NameError"], "`import x as y` only renames the local binding; the module's own __name__ stays 'math'."),
        M("import-resolution", "medium", "Where does Python look when resolving `import foo`?", "sys.modules cache first, then the entries of sys.path in order", ["Only the current directory", "The PATH environment variable", "The internet package index"], "A cached module is reused; otherwise finders search sys.path (script dir, PYTHONPATH, stdlib, site-packages)."),
        M("import-resolution", "hard", "Why does naming your file random.py or json.py cause strange errors?", "It can shadow the standard-library module earlier on sys.path", ["Python forbids those filenames", "It disables the standard library", "It only affects Windows"], "The script's directory comes first on sys.path, so `import random` may load your file instead."),
        M("virtualenvs", "easy", "What problem does a virtual environment solve?", "It isolates a project's dependencies from other projects and the system Python", ["It makes Python run faster", "It compiles Python to native code", "It encrypts source files"], "Each environment has its own site-packages, avoiding version conflicts."),
        M("virtualenvs", "medium", "Which command creates a virtual environment named .venv using only the standard library?", "python -m venv .venv", ["pip install venv .venv", "python --new-env .venv", "virtualenv-create .venv"], "The built-in venv module creates it; then activate it and use pip inside."),
        M("dependencies", "medium", "Why pin versions in requirements.txt (e.g. requests==2.32.3)?", "To get reproducible installs instead of whatever the newest release happens to be", ["Because pip cannot install without versions", "To make packages smaller", "Pinned packages never have vulnerabilities"], "Pinning gives repeatable builds; you must still update periodically to receive security fixes."),
        M("dependencies", "medium", "Which practice best reduces supply-chain risk when adding a dependency?", "Verify the package name and maintainer, pin versions, and audit it with a vulnerability scanner", ["Install the first search result", "Install with sudo so it has permissions", "Disable hash checking to avoid errors"], "Typosquatted or compromised packages are a real attack path; pin, review and scan."),
        O("logging", "medium", "What does this program write to standard output (stdout) with the default logging setup?", "import logging\nlogging.warning('w')\nlogging.info('i')\nprint('done')", "done", ["w\ni\ndone", "i\ndone", "done\nw"], "Logging writes to stderr, not stdout, and the root default level is WARNING, so only 'w' goes to stderr; stdout shows just 'done'. (The runner captures stdout only.)"),
        M("logging", "medium", "Why use the logging module instead of print() in applications?", "Levels, destinations, formatting and timestamps can be configured without changing the code that emits messages", ["print is deprecated", "logging is always faster", "print cannot show strings"], "Logging separates what is reported from where and how it is shown."),
        O("config-env", "medium", "What is printed?", "import os\nos.environ['APP_MODE'] = 'test'\nprint(os.getenv('APP_MODE'), os.getenv('MISSING'), os.getenv('MISSING', 'default'))", "test None default", ["test KeyError default", "None None default", "test '' default"], "os.getenv returns None (or the supplied default) for missing keys, unlike os.environ[...] which raises KeyError."),
        M("config-env", "medium", "Where should API keys and database passwords live in a Python app?", "In environment variables or a secrets manager, not in source code or version control", ["In a constant at the top of the module", "In a comment next to the code that uses them", "In the git repository so the team shares them"], "Secrets in source end up in history and logs; load them from the environment at runtime."),
        O("safe-errors", "medium", "What is printed?", "def parse(s):\n    try:\n        return int(s)\n    except (ValueError, TypeError):\n        return None\n\nprint(parse('12'), parse('x'), parse(None))", "12 None None", ["12 ValueError TypeError", "12 None TypeError", "12 0 0"], "Catch the narrow, expected exceptions and return a defined fallback; unexpected errors still surface."),
        M("safe-errors", "medium", "A web handler catches an exception. What should the client response contain?", "A generic message; log the details (not secrets) server-side", ["The full traceback", "The database connection string for debugging", "Nothing, the server must crash"], "Tracebacks and configuration leak implementation details to attackers; log them privately instead."),
    ]
